import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { randomBytes, scrypt as scryptCb, timingSafeEqual, createHash } from 'node:crypto';
import { promisify } from 'node:util';
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const root=dirname(fileURLToPath(import.meta.url)), data=resolve(process.env.DATA_DIR||join(root,'data'));
mkdirSync(data,{recursive:true}); mkdirSync(join(data,'uploads'),{recursive:true});
const db=new DatabaseSync(join(data,'persona.sqlite')); db.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,name TEXT,password TEXT,profile TEXT DEFAULT '{}',created INTEGER);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires INTEGER);
CREATE TABLE IF NOT EXISTS chats(id INTEGER PRIMARY KEY,title TEXT,kind TEXT,owner INTEGER REFERENCES users(id),theme TEXT DEFAULT '#a3e7c6',description TEXT DEFAULT '',invite TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS members(chat_id INTEGER REFERENCES chats(id),user_id INTEGER REFERENCES users(id),role TEXT DEFAULT 'member',nickname TEXT DEFAULT '',last_read INTEGER DEFAULT 0,PRIMARY KEY(chat_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,chat_id INTEGER REFERENCES chats(id),user_id INTEGER REFERENCES users(id),body TEXT,file_id TEXT,reply_to INTEGER,created INTEGER,edited INTEGER DEFAULT 0,pinned INTEGER DEFAULT 0,nonce TEXT,UNIQUE(user_id,nonce));
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,user_id INTEGER,chat_id INTEGER,name TEXT,mime TEXT,size INTEGER);
CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER REFERENCES messages(id) ON DELETE CASCADE,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS blocks(user_id INTEGER,target_id INTEGER,PRIMARY KEY(user_id,target_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,user_id INTEGER,message_id INTEGER,reason TEXT,created INTEGER);
CREATE INDEX IF NOT EXISTS msg_chat ON messages(chat_id,id);
`);
const get=(s,...p)=>db.prepare(s).get(...p), all=(s,...p)=>db.prepare(s).all(...p), run=(s,...p)=>db.prepare(s).run(...p);
const hash=x=>createHash('sha256').update(x).digest('hex'), scrypt=promisify(scryptCb);
const fail=(code,message)=>{throw Object.assign(new Error(message),{code})};
const clean=(v,max=200)=>typeof v==='string'?v.trim().slice(0,max):'';
const user=u=>({id:u.id,username:u.username,name:u.name,profile:JSON.parse(u.profile)});
const member=(cid,uid)=>get('SELECT * FROM members WHERE chat_id=? AND user_id=?',cid,uid)||fail(403,'Нет доступа к беседе');
const admin=(cid,uid)=>{const m=member(cid,uid);if(!['owner','admin'].includes(m.role))fail(403,'Нужны права администратора');return m};
const streams=new Map(), limits=new Map();
function event(cid){for(const m of all('SELECT user_id FROM members WHERE chat_id=?',cid))for(const r of streams.get(m.user_id)||[])r.write('data: refresh\n\n')}
function limit(key,max=120){const now=Date.now(),v=limits.get(key);if(!v||now-v.at>60000){limits.set(key,{at:now,n:1});return}if(++v.n>max)fail(429,'Слишком много запросов. Подождите минуту.')}
setInterval(()=>{for(const [k,v] of limits)if(Date.now()-v.at>60000)limits.delete(k);run('DELETE FROM sessions WHERE expires<?',Date.now())},60000).unref();
async function body(req,max=150000){let n=0,parts=[];for await(const chunk of req){n+=chunk.length;if(n>max)fail(413,'Файл или запрос слишком большой');parts.push(chunk)}return Buffer.concat(parts)}
async function json(req){try{return JSON.parse((await body(req)).toString()||'{}')}catch(e){if(e.code)throw e;fail(400,'Некорректный запрос')}}
function messages(cid,before=Number.MAX_SAFE_INTEGER,q=''){return all(`SELECT m.*,u.name,u.username,u.profile,mb.nickname FROM messages m JOIN users u ON u.id=m.user_id LEFT JOIN members mb ON mb.chat_id=m.chat_id AND mb.user_id=m.user_id WHERE m.chat_id=? AND m.id<? AND m.body LIKE ? ORDER BY m.id DESC LIMIT 100`,cid,before,'%'+q+'%').reverse().map(m=>({...m,profile:JSON.parse(m.profile),file:m.file_id?get('SELECT id,name,mime,size FROM files WHERE id=?',m.file_id):null,reactions:all('SELECT emoji,user_id FROM reactions WHERE message_id=?',m.id)}))}
const server=http.createServer(async(req,res)=>{
 res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Referrer-Policy','same-origin');res.setHeader('X-Frame-Options','DENY');res.setHeader('Cache-Control','no-store');
 res.setHeader('Content-Security-Policy',"default-src 'self'; img-src 'self' data:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; object-src 'none'; base-uri 'none'");
 const send=(value,status=200)=>{res.writeHead(status,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify(value))};
 try{
 const url=new URL(req.url,'http://localhost'),path=url.pathname,method=req.method;
 if(path==='/health')return send({ok:true});
 if(!path.startsWith('/api/')){const assets={'/':'index.html','/app.js':'app.js','/style.css':'style.css'};if(!assets[path])fail(404,'Не найдено');res.setHeader('Content-Type',path.endsWith('.js')?'text/javascript; charset=utf-8':path.endsWith('.css')?'text/css; charset=utf-8':'text/html; charset=utf-8');return res.end(readFileSync(join(root,'public',assets[path])))}
 if(!['GET','HEAD'].includes(method)){const expected=process.env.APP_ORIGIN||`http://${req.headers.host}`;if(req.headers.origin&&req.headers.origin!==expected)fail(403,'Недопустимый источник запроса');if(req.headers['sec-fetch-site']==='cross-site')fail(403,'Недопустимый источник запроса')}
 limit(req.socket.remoteAddress,300);
 if(path==='/api/register'||path==='/api/login'){
 if(method!=='POST')fail(405,'Недопустимый метод');limit('login:'+req.socket.remoteAddress,15);const b=await json(req),username=clean(b.username,32).toLowerCase(),password=b.password;
 if(!/^[a-z0-9_]{3,32}$/.test(username)||typeof password!=='string'||password.length<10||password.length>128)fail(400,'Логин: 3–32 латинских символа. Пароль: 10–128 символов.');
 let u=get('SELECT * FROM users WHERE username=?',username);
 if(path==='/api/register'){if(process.env.REGISTRATION_CODE&&b.code!==process.env.REGISTRATION_CODE)fail(403,'Неверный код регистрации');if(u)fail(409,'Имя пользователя уже занято');const salt=randomBytes(16).toString('hex'),pw=Buffer.from(await scrypt(password,salt,64)).toString('hex');const id=run('INSERT INTO users(username,name,password,created) VALUES(?,?,?,?)',username,clean(b.name,60)||username,salt+':'+pw,Date.now()).lastInsertRowid;u=get('SELECT * FROM users WHERE id=?',id)}
 else{const [salt,pw]=(u?.password||'dummy:'+ '0'.repeat(128)).split(':');if(!timingSafeEqual(Buffer.from(await scrypt(password,salt,64)),Buffer.from(pw,'hex'))||!u)fail(401,'Неверный логин или пароль')}
 const token=randomBytes(32).toString('hex');run('INSERT INTO sessions VALUES(?,?,?)',hash(token),u.id,Date.now()+30*86400000);res.setHeader('Set-Cookie',`persona=${token}; HttpOnly; SameSite=Strict; Path=/; Max-Age=2592000${process.env.COOKIE_SECURE==='1'?'; Secure':''}`);return send(user(u));}
 const token=(req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('persona='))?.slice(8)||'';
 const session=get('SELECT * FROM sessions WHERE token=? AND expires>?',hash(token),Date.now());if(!session)fail(401,'Войдите в аккаунт');const uid=session.user_id,u=get('SELECT * FROM users WHERE id=?',uid);
 if(path==='/api/me'&&method==='GET')return send(user(u));
 if(path==='/api/logout'&&method==='POST'){run('DELETE FROM sessions WHERE token=?',hash(token));for(const r of streams.get(uid)||[])r.end();res.setHeader('Set-Cookie','persona=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0');return send({ok:true})}
 if(path==='/api/events'){res.writeHead(200,{'Content-Type':'text/event-stream','Connection':'keep-alive','X-Accel-Buffering':'no'});res.write('data: connected\n\n');if(!streams.has(uid))streams.set(uid,new Set());streams.get(uid).add(res);const timer=setInterval(()=>{if(!get('SELECT token FROM sessions WHERE token=? AND expires>?',hash(token),Date.now()))return res.end();res.write(': heartbeat\n\n')},25000);req.on('close',()=>{clearInterval(timer);streams.get(uid)?.delete(res)});return}
 if(path==='/api/profile'&&method==='PATCH'){const b=await json(req),old=JSON.parse(u.profile);let p={...old};for(const [k,n] of [['bio',500],['status',100],['emoji',8],['banner',20]])if(k in b)p[k]=clean(b[k],n);if(b.color&&/^#[\da-f]{6}$/i.test(b.color))p.color=b.color;if(b.avatar!==undefined){if(b.avatar&&!/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(b.avatar))fail(400,'Нужен PNG, JPEG или WebP');p.avatar=clean(b.avatar,100000)}run('UPDATE users SET name=?,profile=? WHERE id=?',clean(b.name,60)||u.name,JSON.stringify(p),uid);for(const c of all('SELECT chat_id FROM members WHERE user_id=?',uid))event(c.chat_id);return send(user(get('SELECT * FROM users WHERE id=?',uid)))}
 if(path==='/api/users'){const q=clean(url.searchParams.get('q'),32);if(q.length<2)return send([]);return send(all('SELECT * FROM users WHERE username LIKE ? AND id!=? LIMIT 20','%'+q+'%',uid).map(user))}
 if(path==='/api/chats'&&method==='GET'){return send(all(`SELECT c.*,mb.role,mb.nickname,mb.last_read,(SELECT body FROM messages WHERE chat_id=c.id ORDER BY id DESC LIMIT 1) last_message,(SELECT max(created) FROM messages WHERE chat_id=c.id) updated,(SELECT count(*) FROM messages WHERE chat_id=c.id AND id>mb.last_read AND user_id!=?) unread FROM chats c JOIN members mb ON mb.chat_id=c.id WHERE mb.user_id=? ORDER BY COALESCE(updated,c.id) DESC`,uid,uid).map(c=>({...c,members:all('SELECT u.id,u.name,u.username,u.profile,m.role,m.nickname,m.last_read FROM members m JOIN users u ON u.id=m.user_id WHERE chat_id=?',c.id).map(m=>({...m,profile:JSON.parse(m.profile)}))})))}
 if(path==='/api/chats'&&method==='POST'){const b=await json(req),target=Number(b.userId),kind=target?'direct':'group';if(target===uid)fail(400,'Выберите другого пользователя');if(target){if(!get('SELECT id FROM users WHERE id=?',target))fail(404,'Пользователь не найден');if(get('SELECT 1 FROM blocks WHERE (user_id=? AND target_id=?) OR (user_id=? AND target_id=?)',uid,target,target,uid))fail(403,'Общение заблокировано');const existing=get("SELECT c.id FROM chats c JOIN members a ON c.id=a.chat_id JOIN members b ON c.id=b.chat_id WHERE c.kind='direct' AND a.user_id=? AND b.user_id=?",uid,target);if(existing)return send(existing)}const title=clean(b.title,80);if(!target&&!title)fail(400,'Введите название беседы');const id=Number(run('INSERT INTO chats(title,kind,owner,invite) VALUES(?,?,?,?)',title,kind,uid,randomBytes(18).toString('hex')).lastInsertRowid);run('INSERT INTO members(chat_id,user_id,role) VALUES(?,?,?)',id,uid,'owner');if(target)run('INSERT INTO members(chat_id,user_id) VALUES(?,?)',id,target);event(id);return send({id})}
 if(path==='/api/join'&&method==='POST'){const b=await json(req),c=get("SELECT * FROM chats WHERE invite=? AND kind='group'",clean(b.invite,100));if(!c)fail(404,'Приглашение не найдено');if(all('SELECT user_id FROM members WHERE chat_id=?',c.id).length>=500)fail(400,'Беседа заполнена');run('INSERT OR IGNORE INTO members(chat_id,user_id) VALUES(?,?)',c.id,uid);event(c.id);return send({id:c.id})}
 const cm=path.match(/^\/api\/chats\/(\d+)(?:\/(\w+))?$/);
 if(cm){const cid=Number(cm[1]),action=cm[2],m=member(cid,uid),c=get('SELECT * FROM chats WHERE id=?',cid);
 if(!action&&method==='PATCH'){admin(cid,uid);const b=await json(req);run('UPDATE chats SET title=?,description=?,theme=?,invite=? WHERE id=?',clean(b.title,80)||c.title,clean(b.description??c.description,500),/^#[\da-f]{6}$/i.test(b.theme)?b.theme:c.theme,b.rotateInvite?randomBytes(18).toString('hex'):c.invite,cid);event(cid);return send({ok:true})}
 if(action==='members'&&method==='PATCH'){admin(cid,uid);const b=await json(req),target=Number(b.userId),tm=member(cid,target);if(tm.role==='owner')fail(403,'Нельзя изменить владельца');if(m.role!=='owner'&&tm.role==='admin')fail(403,'Недостаточно прав');if(b.remove)run('DELETE FROM members WHERE chat_id=? AND user_id=?',cid,target);else{if(m.role!=='owner')fail(403,'Роли назначает владелец');run('UPDATE members SET role=? WHERE chat_id=? AND user_id=?',b.role==='admin'?'admin':'member',cid,target)}event(cid);return send({ok:true})}
 if(action==='nickname'&&method==='PATCH'){const b=await json(req);run('UPDATE members SET nickname=? WHERE chat_id=? AND user_id=?',clean(b.nickname,60),cid,uid);event(cid);return send({ok:true})}
 if(action==='read'&&method==='POST'){const previous=m.last_read;run('UPDATE members SET last_read=COALESCE((SELECT max(id) FROM messages WHERE chat_id=?),0) WHERE chat_id=? AND user_id=?',cid,cid,uid);if(member(cid,uid).last_read!==previous)event(cid);return send({ok:true})}
 if(action==='messages'&&method==='GET')return send(messages(cid,Number(url.searchParams.get('before'))||Number.MAX_SAFE_INTEGER,clean(url.searchParams.get('q'),200)));
 if(action==='messages'&&method==='POST'){limit('send:'+uid,60);if(c.kind==='direct'&&get('SELECT 1 FROM blocks b JOIN members m ON m.user_id=b.user_id WHERE m.chat_id=? AND b.target_id=?',cid,uid))fail(403,'Общение заблокировано');const b=await json(req),text=clean(b.body,4096),fid=clean(b.fileId,100)||null,reply=Number(b.replyTo)||null,nonce=clean(b.nonce,80)||randomBytes(16).toString('hex');if(!text&&!fid)fail(400,'Сообщение пустое');if(fid&&!get('SELECT id FROM files WHERE id=? AND user_id=? AND chat_id=?',fid,uid,cid))fail(403,'Нет доступа к файлу');if(reply&&!get('SELECT id FROM messages WHERE id=? AND chat_id=?',reply,cid))fail(400,'Ответ не найден');run('INSERT OR IGNORE INTO messages(chat_id,user_id,body,file_id,reply_to,created,nonce) VALUES(?,?,?,?,?,?,?)',cid,uid,text,fid,reply,Date.now(),nonce);event(cid);return send({ok:true})}
 if(action==='upload'&&method==='POST'){const bytes=await body(req,25*1024*1024);const id=randomBytes(20).toString('hex'),name=clean(decodeURIComponent(req.headers['x-filename']||'file'),150),mime=clean(req.headers['content-type'],100);writeFileSync(join(data,'uploads',id),bytes);run('INSERT INTO files VALUES(?,?,?,?,?,?)',id,uid,cid,name,mime,bytes.length);return send({id,name})}
 }
 const mm=path.match(/^\/api\/messages\/(\d+)(?:\/(\w+))?$/);
 if(mm){const id=Number(mm[1]),m=get('SELECT * FROM messages WHERE id=?',id);if(!m)fail(404,'Сообщение не найдено');const mb=member(m.chat_id,uid),b=method==='DELETE'?{}:await json(req);
 if(mm[2]==='reaction'&&method==='POST'){const emoji=clean(b.emoji,8);if(!['❤️','👍','🔥','😂','👀','✨'].includes(emoji))fail(400,'Неизвестная реакция');if(get('SELECT 1 FROM reactions WHERE message_id=? AND user_id=? AND emoji=?',id,uid,emoji))run('DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?',id,uid,emoji);else run('INSERT INTO reactions VALUES(?,?,?)',id,uid,emoji)}
 else if(mm[2]==='pin'&&method==='POST'){admin(m.chat_id,uid);run('UPDATE messages SET pinned=? WHERE id=?',m.pinned?0:1,id)}
 else if(method==='PATCH'){if(m.user_id!==uid)fail(403,'Можно редактировать только свои сообщения');const text=clean(b.body,4096);if(!text)fail(400,'Сообщение пустое');run('UPDATE messages SET body=?,edited=1 WHERE id=?',text,id)}
 else if(method==='DELETE'){if(m.user_id!==uid&&!['owner','admin'].includes(mb.role))fail(403,'Недостаточно прав');run('DELETE FROM messages WHERE id=?',id)}else fail(405,'Недопустимый метод');event(m.chat_id);return send({ok:true})}
 if(path.startsWith('/api/files/')&&method==='GET'){const f=get('SELECT * FROM files WHERE id=?',path.split('/').pop());if(!f)fail(404,'Файл не найден');member(f.chat_id,uid);res.setHeader('Content-Type',/^(image\/(png|jpeg|webp|gif)|audio\/(webm|ogg|mpeg)|video\/mp4)$/.test(f.mime)?f.mime:'application/octet-stream');res.setHeader('Content-Disposition',`attachment; filename*=UTF-8''${encodeURIComponent(f.name)}`);return res.end(readFileSync(join(data,'uploads',f.id)))}
 if(path==='/api/block'&&method==='POST'){const b=await json(req);if(!get('SELECT id FROM users WHERE id=?',Number(b.userId)))fail(404,'Пользователь не найден');if(b.remove)run('DELETE FROM blocks WHERE user_id=? AND target_id=?',uid,Number(b.userId));else run('INSERT OR IGNORE INTO blocks VALUES(?,?)',uid,Number(b.userId));return send({ok:true})}
 if(path==='/api/reports'&&method==='POST'){const b=await json(req),m=get('SELECT * FROM messages WHERE id=?',Number(b.messageId));if(!m)fail(404,'Сообщение не найдено');member(m.chat_id,uid);run('INSERT INTO reports(user_id,message_id,reason,created) VALUES(?,?,?,?)',uid,m.id,clean(b.reason,1000),Date.now());return send({ok:true})}
 fail(404,'Не найдено');
 }catch(e){if(!res.headersSent)send({error:e.code&&typeof e.code==='number'?e.message:'Ошибка сервера'},typeof e.code==='number'?e.code:500);else res.end();if(!e.code)console.error(e)}
});
server.listen(Number(process.env.PORT)||3000,process.env.HOST||'127.0.0.1',()=>console.log(`Persona: http://${process.env.HOST||'127.0.0.1'}:${process.env.PORT||3000}`));
